create or replace view public.anaira_hotel_booking_admin_records with (security_invoker=true) as
select t.id,t.tenant_id,t.booking_id as hms_reservation_id,t.customer_id,t.state,t.amount,t.currency,t.created_at,t.updated_at,r.reservation_code,r.booking_reference,r.status as reservation_status,r.check_in,r.check_out,r.adults,r.children,r.room_type_id,rt.name as room_type_name,r.room_id,rm.room_number,r.rate_plan_id,rp.name as rate_plan_name,rp.code as rate_plan_code,r.rate as nightly_rate,r.total_amount,r.deposit_amount,r.paid_amount,r.balance_amount,r.payment_status,r.payment_method,r.payment_reference,r.payment_proof_url,coalesce(g.full_name,c.full_name) as guest_name,coalesce(g.phone,c.phone) as guest_phone,coalesce(g.email,c.email) as guest_email,ps.id as payment_submission_id,ps.status as payment_submission_status,ps.reference as payment_submission_reference,ps.proof_url as payment_submission_proof_url,ps.submitted_at as payment_submitted_at,ps.verified_at as payment_verified_at,t.payload->>'source' as booking_source from public.crm_booking_transactions t left join public.hms_reservations r on r.id=t.booking_id and r.restaurant_id=t.tenant_id left join public.hms_guests g on g.id=r.guest_id left join public.crm_customers c on c.id=t.customer_id left join public.hms_room_types rt on rt.id=r.room_type_id left join public.hms_rooms rm on rm.id=r.room_id left join public.hms_rate_plans rp on rp.id=r.rate_plan_id left join lateral (select x.* from public.hms_booking_payment_submissions x where x.reservation_id=r.id order by x.created_at desc limit 1) ps on true;
